// Trusted Node request only. All fields are compared against an immutable quote in Node.
const b=$input.first().json.body ?? {};
const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if(b.agentKey!=='ancfz'||typeof b.ticketId!=='string'||!uuid.test(b.ticketId))throw Error('Invalid agent/ticket');
if(typeof b.quotationId!=='string'||!uuid.test(b.quotationId))throw Error('Invalid quotation ID');
if(typeof b.orderReference!=='string'||!/^[A-Za-z0-9_-]{1,120}$/.test(b.orderReference))throw Error('Invalid 2Checkout order reference');
if(typeof b.providerPaymentId!=='string'||!/^[A-Za-z0-9_-]{1,120}$/.test(b.providerPaymentId))throw Error('Invalid provider payment ID');
if(typeof b.externalReference!=='string'||!/^ANCFZ-[A-Za-z0-9_-]{8,160}$/.test(b.externalReference))throw Error('Invalid external reference');
if(b.currency!=='AED'||typeof b.amount!=='string'||!/^[1-9]\d{0,7}\.\d{2}$|^0\.(?!00)\d{2}$/.test(b.amount))
  throw Error('Invalid authorized amount/currency');
return [{json:{ticketId:b.ticketId,quotationId:b.quotationId,orderReference:b.orderReference,
  providerPaymentId:b.providerPaymentId,
  externalReference:b.externalReference,amount:b.amount,currency:b.currency}}];

// This runs after a FRESH authenticated GET, never after a redirect or POST.
// COMPLETE is accepted ONLY with matching provider reference, amount and currency.
const r=$input.first().json;
const expected=$('Validate Verification Request').first().json;
if(!r||typeof r!=='object'||Array.isArray(r))throw Error('Invalid 2Checkout verification response');
const ref=r.RefNo ?? r.OrderNo;
if(ref!==expected.orderReference)throw Error('2Checkout order reference mismatch');
if(r.ExternalReference!==expected.externalReference)throw Error('2Checkout external reference mismatch');
if(r.Currency!==expected.currency)throw Error('2Checkout currency mismatch');
if(typeof r.GrossPrice!=='string'||r.GrossPrice!==expected.amount)
  throw Error('2Checkout gross price mismatch');
const providerStatus=r.Status;
if(!['COMPLETE','PENDING','DECLINED','REFUNDED'].includes(providerStatus))
  throw Error('Unsupported 2Checkout order status');
const paid=providerStatus==='COMPLETE';
return [{json:{
  status:paid?'verified_test_payment':providerStatus==='PENDING'?'payment_pending':
    providerStatus==='DECLINED'?'payment_declined':'payment_refunded',
  verified:paid, provider:'2checkout_mock', providerStatus,
  orderReference:ref,providerPaymentId:expected.providerPaymentId,
  externalReference:expected.externalReference,
  ticketId:expected.ticketId,quotationId:expected.quotationId,
  amount:expected.amount,currency:expected.currency,
  invoiceReference:typeof r.InvoiceID==='string'?r.InvoiceID:null,
}}];
